using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
namespace RaceDay.Web;
public class ApiClient(HttpClient http, IHttpContextAccessor accessor) { readonly JsonSerializerOptions json=new(){PropertyNameCaseInsensitive=true}; HttpRequestMessage Request(HttpMethod method,string path){var request=new HttpRequestMessage(method,path);var token=accessor.HttpContext?.Session.GetString("token");if(!string.IsNullOrWhiteSpace(token))request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);return request;} public async Task<T?> Get<T>(string path){using var response=await http.SendAsync(Request(HttpMethod.Get,path));return response.IsSuccessStatusCode?await response.Content.ReadFromJsonAsync<T>(json):default;} public async Task<HttpResponseMessage> SendJson(HttpMethod method,string path,object body){var request=Request(method,path);request.Content=JsonContent.Create(body);return await http.SendAsync(request);} public async Task<HttpResponseMessage> Delete(string path)=>await http.SendAsync(Request(HttpMethod.Delete,path)); public async Task<string?> Upload(string path,IFormFile file){using var form=new MultipartFormDataContent();await using var stream=file.OpenReadStream();form.Add(new StreamContent(stream){Headers={ContentType=new MediaTypeHeaderValue(file.ContentType)}},"file",file.FileName);var request=Request(HttpMethod.Post,path);request.Content=form;using var response=await http.SendAsync(request);if(!response.IsSuccessStatusCode)return null;using var data=JsonDocument.Parse(await response.Content.ReadAsStringAsync());var url=data.RootElement.GetProperty("url").GetString();return url?.Replace("http://api:8080/","http://localhost:8080/",StringComparison.OrdinalIgnoreCase);} }
